        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_print_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.print()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf91500.btn_print_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_self_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_self_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_self_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91500.btn_self_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_print = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_printReq") ? $c.util.getComponent("dma_printReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setComma
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setComma = function () {
    /* sdd-asis-lifecycle:begin setComma — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.num.formatNumber($('#ipt_isuShrs')[0]);
    $c.num.formatNumber($('#ipt_wrntIsuRnd')[0]);
    $c.num.formatNumber($('#ipt_stkRelCorpbndExerPrc')[0]);
    $c.util.getComponent('txt_isuShrsTd').setLabel($c.util.getComponent('ipt_isuShrs').getValue());
    $c.util.getComponent('txt_wrntIsuRndTd').setLabel($c.util.getComponent('ipt_wrntIsuRnd').getValue());
    $c.util.getComponent('txt_stkRelCorpbndExerPrcTd').setLabel($c.util.getComponent('ipt_stkRelCorpbndExerPrc').getValue());
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.open_modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.open_modify = function () {
    /* sdd-asis-lifecycle:begin open_modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const stdcdType = $c.util.getComponent('ipt_stdcdType').getValue();
    const stdCd = $c.util.getComponent('ipt_stdCd').getValue();
    const form = (document.JLDINF91500 || { elements: [] });
    $c.util.getComponent('ipt_modDelCd').setValue("mod");
    fn_passwordWin(form);
    /* sdd-asis-lifecycle:end */
};


/**
