    /* sdd-asis-lifecycle:begin open_delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const stdcdType = $c.util.getComponent('ipt_stdcdType').getValue();
    const stdCd = $c.util.getComponent('ipt_stdCd').getValue();
    const form = (document.JLDINF91500 || { elements: [] });
    $c.util.getComponent('ipt_modDelCd').setValue("del");
    fn_passwordWin(form);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.go_modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.go_modify = async function () {
    /* sdd-asis-lifecycle:begin go_modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.JLDINF91500 || { elements: [] });
    const url = "/stdcd/stdcdModify.do?method=stdcdModify&type=5&std_cd=" + $c.util.getComponent('ipt_stdCd').getValue();
    fm.action = url;
    fm.target = "_top";
    await moveUrl(url, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.go_delete
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
