*/
scwin.go_delete = function () {
    /* sdd-asis-lifecycle:begin go_delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const stdcdType = $c.util.getComponent('ipt_stdcdType').getValue();
    const stdCd = $c.util.getComponent('ipt_stdCd').getValue();
    const form = (document.JLDINF91500 || { elements: [] });
    fn_stdCdDelWin(form);
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.print = async function () {
    /* sdd-asis-lifecycle:begin fn_print — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await $c.win.confirm("신주인수권증권 상세정보를 출력하시겠습니까?")) {
        return false;
    } else {
        const std_cd = $c.util.getComponent('dma_printReq').get('stdCd');
        $.ajax({ type: "POST", async: false, url: "/srch/srch.do?method=srchReportCommonAjax&serviceName=srchReport5&std_cd=" + std_cd, data: {  }, success: async function(data) {
                    const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                    const form = (document.newReportForm || { elements: [] });
                    for (key in result) {
                        if (form[camelize(key)]) {
                            form[camelize(key)].value = result[key];
                        }
                    }
                    await scwin.tx_fn_print();
                }, error: async function(request, status, error) {
                    await $c.win.alert("장애발생.");
                    return;
                }, complete: function() {

                } });
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.printOld
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.printOld = async function () {
    /* sdd-asis-lifecycle:begin fn_print_old — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await $c.win.confirm("신주인수권증권 상세정보를 출력하시겠습니까?")) {
        return false;
    } else {
        const formName = (document.JLDINF91500 || { elements: [] });
        const std_cd = $c.util.getComponent('dma_printReq').get('stdCd');
        const rexName = "JLDINF91500";
        const dataType = "XML";
        const dataLocation = "/srch/srch.do?method=srchReport5&std_cd=" + std_cd;
        const dataXPath = "main/rpt1";
        const mktGubun = "1";
        fn_PrintPreView_DB(rexName, dataType, dataLocation, dataXPath);
    }
    /* sdd-asis-lifecycle:end */
};
